  FT["PH-H2269"] = {"id":"PH-H2269","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2540_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Olutanga市","en":"An Act Creating Certain Barrios in the Municipality of Olutanga, Province of Zamboanga del Sur","orig":"An Act Creating Certain Barrios in the Municipality of Olutanga, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2540","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2540_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2269-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Olutanga, Province of Zamboanga del Sur, are converted into barrios thereof:\n1. Sitio Baganipay to be known as the barrio of Malipay;\n2. Sitio Tabian to be known as the barrio of Mercedes;\n3. Sitio Sibayog to be known as the barrio of Salagunting;\n4. Sitio Tandu Taba to be known as the barrio of Estancia;\n5. Sitio Bagurod to be known as the barrio of Balasan;\n6. Sitio Dao to be known as the barrio of Dayag; and\n7. Sitio Cawilan Sur to be known as the barrio of Fama."}},{"id":"PH-H2269-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2270"] = {"id":"PH-H2270","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2541_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Liargao市","en":"An Act Creating Certain Barrios in the Municipality of Liargao, Province of Zamboanga del Sur","orig":"An Act Creating Certain Barrios in the Municipality of Liargao, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2541","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2541_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2270-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Lumangoy, Lumpanid, Montay, Midsapin, Patang, Dipalusan, Guminambon, Dinuyog, San Miguel, Bibilog and Dipalutao in the Municipality of Liargao, Province of Zamboanga Sur, are converted into barrios of said municipality to be known as the barrios of Lumangoy, Lumpanid, Montay, Midsapin, Patang, Dipalusan, Guminambon, Dinuyog, San Miguel, Bibilog and Dipaluto, respectively."}},{"id":"PH-H2270-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2271"] = {"id":"PH-H2271","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2542_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of Certain Barrios in the Municipality of Olutanga, Province of Zamboanga del Sur","orig":"An Act Changing the Names of Certain Barrios in the Municipality of Olutanga, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2542","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2542_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2271-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the following barrios in the Municipality of Olutanga, Province of Zamboanga del Sur, are changed as follows:\n1. Barrio Pinalim to Barrio Bagdad;\n2. Barrio Tandu Comot to Barrio Katipunan;\n3. Barrio Bongalan to Barrio Esperanza;\n4. Barrio Bontalian to Barrio Tuburan;\n5. Barrio Sagasa to Barrio Malinao;\n6. Barrio Calabasa to Barrio Abunda;\n7. Barrio Subanipa to Barrio solar;\n8. Barrio Galais to Barrio Calines;\n9. Barrio Gawilan to Barrio Noque;\n10. Barrio Taguisian to Barrio Tampohan;\n11. Barrio Cabatuan to Barrio Catipan; and\n12. Barrio Talusan to Barrio Jerusalim."}},{"id":"PH-H2271-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2272"] = {"id":"PH-H2272","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2543_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Batangas市","en":"An Act Creating the Barrio of Maruclap in the Municipality of Batangas, Province of Batangas","orig":"An Act Creating the Barrio of Maruclap in the Municipality of Batangas, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2543","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2543_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2272-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Maruclap and Cotocoto in the barrio of Haliging Kanluran, Maarangan in the barrio of Haliging Silangan, Cacawan in the barrio of Sto. Niño, and Payapa in the barrio of Talahib Payapa, all in the Municipality of Batangas, Province of Batangas, are separated from the said barrios, and constituted into a distinct and independent barrio of said municipality to be known as the barrio of Maruclap."}},{"id":"PH-H2272-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
