  FT["PH-H2276"] = {"id":"PH-H2276","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2547_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Barrio Ibabang Banot, Municipality of Gumaca, Province of Quezon, to Gitnang Barrio","orig":"An Act Changing the Name of Barrio Ibabang Banot, Municipality of Gumaca, Province of Quezon, to Gitnang Barrio"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2547","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2547_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2276-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Ibabang Banot, Municipality of Gumaca, Province of Quezon, is hereby changed to Gitnang Barrio."}},{"id":"PH-H2276-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2277"] = {"id":"PH-H2277","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2548_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Barrios and Sitios in the Municipality of Diffun, Province of Nueva Vizcaya","orig":"An Act Naming the Barrios and Sitios in the Municipality of Diffun, Province of Nueva Vizcaya"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2548","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2548_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2277-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios and sitios in the Municipality of Diffun, Province of Nueva Vizcaya, are hereby enumerated and named as follows:\nBarrio San Antonio (formerly known as Calimaturog) with its sitios of Guribang, Batarra and Navarro; Barrio San Isidro with its sitios of Rancho, Silang (formerly known as Magsaysayot) and Mabini (formerly known as Amelingan); Barrio Maria Clara with its sitio of Lucban; Barrio Villa Pascua with its sitio of San Pedro; Barrio Luttuad with its sitio of Capannikian; barrio of Mangandingay, with its sitios of Dallapan and Malini barrio of Gundaway with its sitios of Cabugbogan, Dinait, Diagay, Tarlac (formerly known as Difuncia) and Dumatata; barrio of Cahel with its sitio of Nagbukel; barrio of Liwayway (formerly known as Disinaba) with its sitios of Bayabat, Simbahan and San Francisco; barrio of Ricarte with its sitios of Pakipak, Bontutan, Bender formerly known as Lanna), San Juan and Dinaliang; barrio of Tandang Sora (formerly known as Dumanisi) with its sitios of Andapat, Dumanting, Dapungan, Anonang, Lorad, Hunters (formerly known as Campamiento), Makate, Amugawen and Pena, and the barrios of I. Paredes, Gulac, Bannawag, La Paz, Salvacion, Sto. Tomas, Saguday, Balagbag and San Marcos (formerly known as Cannuanga)."}},{"id":"PH-H2277-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2278"] = {"id":"PH-H2278","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2549_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Barrio Ipil Pequeno in the Municipality of Echague, Province of Isabela, to Barrio Quezon","orig":"An Act Changing the Name of Barrio Ipil Pequeno in the Municipality of Echague, Province of Isabela, to Barrio Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2549","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2549_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2278-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Ipil Pequeno in the Municipality of Echague, Province of Isabela, is hereby changed to Barrio Quezon."}},{"id":"PH-H2278-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2279"] = {"id":"PH-H2279","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2550_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Dividing the Barrio of Manaring in the Municipality of Ilagan, Province of Isabela, into Two Barrios to be Known as Barrio Manaring Primero and Barrio Manaring Segundo","orig":"An Act Dividing the Barrio of Manaring in the Municipality of Ilagan, Province of Isabela, into Two Barrios to be Known as Barrio Manaring Primero and Barrio Manaring Segundo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2550","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2550_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2279-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Manaring in the Municipality of Ilagan, Province of Isabela, is hereby divided into two barrios to be known as Barrio Manaring Primero and Barrio Manaring Segundo."}},{"id":"PH-H2279-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2280"] = {"id":"PH-H2280","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2551_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Primary School of Barrio Malabo in the Municipality of Valencia, Province of Negros Oriental, as Carson Primary School","orig":"An Act Naming the Primary School of Barrio Malabo in the Municipality of Valencia, Province of Negros Oriental, as Carson Primary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2551","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2551_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2280-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The primary school of Barrio Malabo, Municipality of Valencia, Province of Negros Oriental, is hereby named Carson Primary School."}},{"id":"PH-H2280-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2281"] = {"id":"PH-H2281","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2552_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Hilongos市","en":"An Act Creating Certain Barrios in the Municipality of Hilongos, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Hilongos, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2552","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2552_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2281-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Hilongos, Province of Leyte, are constituted or converted as barrios of said municipality, to wit:\n1. The sitios of Tagnate, Mahangin, Panas and Hibunlod to be known as the barrio of Tagnate;\n2. The sitios of Agutayan, Lagtangon, Kandasig and Katungawan to be known as the barrio of Agutayan;\n3. The sitios of Campina and Matigbaw to be known as the barrio of Campina; and\n4. The sitio of Magnangoy to be known as the barrio of Magnangoy."}},{"id":"PH-H2281-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2282"] = {"id":"PH-H2282","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2553_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Sindangan市","en":"An Act Creating the Barrio of Siayan in the Municipality of Sindangan, Province of Zamboanga del Norte","orig":"An Act Creating the Barrio of Siayan in the Municipality of Sindangan, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2553","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2553_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2282-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Siayan, Bentol, Litalet, Dibalan, Colaton, Moyo Gamay, Pasi and Dalongdong in the Municipality of Sindangan, Province of Zamboanga del Norte, are constituted into a distinct and independent barrio of said municipality to be known as the barrio of Siayan."}},{"id":"PH-H2282-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2283"] = {"id":"PH-H2283","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2554_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Rosario市","en":"An Act Creating Certain Barrios in the Municipality of Rosario, Province of Batangas","orig":"An Act Creating Certain Barrios in the Municipality of Rosario, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2554","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2554_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2283-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios in the Municipality of Rosario, Province of Batangas, are constituted into barrios of said municipality as follows:\n1. The barrio of Macalamcam is divided into two distinct and independent barrios to be known as the barrios of Macalamcam-A and Macalamcam-B;\n2. The barrio of Putingkahoy is divided into two distinct and independent barrios to be known as the barrios of Putingkahoy and Nazi;\n3. The barrio of Matamis is divided into two distinct and independent barrios to be known as the barrios of Matamis and Antipolo;\n4. The barrio of Mayuro is divided into two distinct and independent barrios to be known as the barrios of Mayuro and Bayawang, and\n5. The barrio of Tulos is divided into two distinct and independent barrios to be known as the barrios of Tulos and Calantas.\nThe boundaries of the above-mentioned barrios shall be determined and fixed by the Municipal Council of the Municipality of Rosario, Province of Batangas, within one year from the date of the approval of this Act."}},{"id":"PH-H2283-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Lumbangan, Cantarilya and Makukak in the Municipality of Rosario, Province of Batangas, are constituted into a district and independent barrio of said municipality to be known as the barrio of Lumbangan."}},{"id":"PH-H2283-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2284"] = {"id":"PH-H2284","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2555_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Pulantubig Elementary School at Dumaguete City to Ramon Magsaysay Memorial School","orig":"An Act Changing the Name of Pulantubig Elementary School at Dumaguete City to Ramon Magsaysay Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2555","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2555_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2284-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Pulantubig Elementary School at Dumaguete City is changed to Ramon Magsaysay Memorial School."}},{"id":"PH-H2284-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
