  FT["PH-H2286"] = {"id":"PH-H2286","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2557_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Patao Primary School in the Barrio of Bawod, Municipality of Bantayan, Province of Cebu, to Bawod Primary School","orig":"An Act Changing the Name of the Patao Primary School in the Barrio of Bawod, Municipality of Bantayan, Province of Cebu, to Bawod Primary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2557","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2557_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2286-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Patao Primary School in the barrio of Bawod, Municipality of Bantayan, Province of Cebu, is changed to Bawod Primary School."}},{"id":"PH-H2286-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2287"] = {"id":"PH-H2287","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2558_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrios in the Province of Isabela","orig":"An Act Creating Barrios in the Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2558","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2558_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2287-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of San Agustin, Province of Isabela, are constituted into a barrio of the said municipality, as follows:\nSitios Salay and Narien to Barrio Salay."}},{"id":"PH-H2287-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The following sitios in the Municipality of Tumauini, Province of Isabela, are constituted into a barrio of the said municipality, as follows:\nSitios Sical and Cabal to Barrio Namnama."}},{"id":"PH-H2287-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Puroc No. 6, Salinungan, in the Municipality of San Mateo, Province of Isabela, is hereby converted into a barrio to be known as Barrio Salinungan East."}},{"id":"PH-H2287-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
