  FT["PH-H2308"] = {"id":"PH-H2308","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2580_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Sitio of Bural in the Barrio of Zinundungan, Municipality of Rizal, Province of Cagayan, to San Juan","orig":"An Act Changing the Name of the Sitio of Bural in the Barrio of Zinundungan, Municipality of Rizal, Province of Cagayan, to San Juan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2580","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2580_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2308-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the sitio of Bural in the barrio of Zinundungan, Municipality of Rizal, Province of Cagayan, is changed to San Juan."}},{"id":"PH-H2308-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2309"] = {"id":"PH-H2309","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2581_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Constituting the Sitios of Kay-Poo, Nabiling, Kahawanan, Apartahan and Kalimpay in the Barrio of Tigwi, Municipality of Torrijos, Province of Marinduque, into a Separate Barrio to be Known as the Barrio of Kawayanan","orig":"An Act Constituting the Sitios of Kay-Poo, Nabiling, Kahawanan, Apartahan and Kalimpay in the Barrio of Tigwi, Municipality of Torrijos, Province of Marinduque, into a Separate Barrio to be Known as the Barrio of Kawayanan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2581","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2581_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2309-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Kay-Poo, Nabiling, Kahawanan, Apartahan and Kalimpay in the barrio of Tigwi, Municipality of Torrijos, Province of Marinduque, are hereby constituted into a separate barrio of the said municipality to be known as the barrio of Kawayanan."}},{"id":"PH-H2309-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2310"] = {"id":"PH-H2310","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2582_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrios in the Third District of the Province of Samar","orig":"An Act Creating Barrios in the Third District of the Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2582","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2582_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2310-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Seguinon, Karapdapan, Lusod, Hagnaya, Santa Cruz and Cantomoja in the Municipality of Salcedo, Province of Samar, are converted into barrios of said municipality to be known as the barrios of Seguinon, Karapdapan, Lusod, Hagnaya, Santa Cruz and Cantomoja, respectively."}},{"id":"PH-H2310-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Limbujan in the Municipality of General MacArthur, Province of Samar, is converted into a barrio of said municipality to be known as the barrio of Limbujan."}},{"id":"PH-H2310-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2311"] = {"id":"PH-H2311","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2583_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Isabela","orig":"An Act Creating Certain Barrios in the Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2583","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2583_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2311-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Rang-ayan in the Municipality of Mallig, Province of Isabela, is hereby converted into a barrio to be known as Barrio Rang-ayan."}},{"id":"PH-H2311-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Sta. Rita in the Municipality of Aurora, same province, is hereby converted into a barrio to be known as Barrio Sta. Rita."}},{"id":"PH-H2311-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitios of Balmarin, Belma and Salipan in the Municipality of San Agustin, same province, are hereby constituted into a barrio to be known as Barrio Damabal."}},{"id":"PH-H2311-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2312"] = {"id":"PH-H2312","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2584_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of the Barrio of Crossing Macasilao or Barrio Yonson in the Municipality of Calatrava, and the Barrio of Binabongol in the Municipality of Escalante, Province of Negros Occidental, to Barrio Castellano and Barrio Magsaysay, Respectively","orig":"An Act Changing the Names of the Barrio of Crossing Macasilao or Barrio Yonson in the Municipality of Calatrava, and the Barrio of Binabongol in the Municipality of Escalante, Province of Negros Occidental, to Barrio Castellano and Barrio Magsaysay, Respectively"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2584","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2584_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2312-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Crossing Macasilao or Barrio Yonson in the Municipality of Calatrava, Province of Negros Occidental, is changed to Barrio Castellano."}},{"id":"PH-H2312-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The name of the barrio of Binobongol in the Municipality of Escalante, same province, is changed to Barrio Magsaysay."}},{"id":"PH-H2312-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2313"] = {"id":"PH-H2313","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2585_1959.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Negros Occidental","orig":"An Act Creating Certain Barrios in the Province of Negros Occidental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2585","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2585_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2313-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Jerusalem, Macabal-ong, Manuyo, Campo Negros, Siwahon and Alimatoc in the barrio of Cabahug, Municipality of Cadiz, Province of Negros Occidental, are separated from said barrio and constituted into a distinct and independent barrio of said municipality to be known as the barrio of Magsaysay."}},{"id":"PH-H2313-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Bat-us and Punao and haciendas Refugio and Cubay in the Municipality of Calatrava, same province, are constituted into a distinct and independent barrio of said municipality to be known as the barrio of Refugio."}},{"id":"PH-H2313-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The following sitios and haciendas in the Municipality of Manapla, same province, are constituted as barrios, to wit:\n(a) The sitio of Sta. Tereza, and haciendas Belen, Anita, Mose, Balew, Sicaba, Lacson, Fortuna and Apanoy into a distinct and independent barrio of said municipality to be known as the barrio of Sta. Tereza;\n(b) The sitio of Pta. Salong, and haciendas Catalina and Nagsico, and the sitios of Pinanonghan, Locdo and To-ong into a distinct and independent barrio of said municipality to be known as the barrio of Pta. Salong;\n(c) The sitios of Pta. Mesa, Cotosan and Olamhay, and haciendas Tividavo, Cogon (Ascona), Busay and Lumayagan into a distinct and independent barrio of said municipality to be known as the barrio of Pta. Mesa; and\n(d) The sitio of Purissima, and haciendas Begonia, Candelaria, Patlagan, Guicay, Remedios, Pandayan, Tagbac and Central Manapla into a distinct and independent barrio of said municipality to be known as the barrio of Purissima."}},{"id":"PH-H2313-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The following haciendas and sitios in the Municipality of Talisay, same province, are constituted as barrios, to wit:\n(a) The haciendas of San Jacinto, Gusa-Lacson, Manaul, Bacong-Gonzaga, Socorro-Lizares, Matab-ang (Nilo Lizares), Minulwan (Labayen), Matab-ang (Ledesma and Granada), and Vista-Lacson as a distinct and independent barrio of said municipality to be known as the barrio of Matab-ang;\n(b) The sitio of Busay, and the haciendas of Epigenio, Bagacay-Lacson, Minulwan-Lizares, Cabanbanan (Osmeña) Cafe-Kilayko, Virgen del Pilar and Binaliwan (Yusay and Pison) as a distinct and independent barrio of said municipality to be known as the barrio of Epigenio Lizares; and\n(c) The hacienda and sitios of To-ong, Bocboc, Cabakahan, Bagacay, Magbuyo, Masanglad, Mambucano, Tambara and Hacienda Semillano-Honores as a distinct and independent barrio of said municipality to be known as the barrio of Cabatangan."}},{"id":"PH-H2313-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2314"] = {"id":"PH-H2314","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2586_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Coron Elementary School in the Municipality of Coron, Province of Palawan, to Claudio Sandoval Elementary School","orig":"An Act Changing the Name of the Coron Elementary School in the Municipality of Coron, Province of Palawan, to Claudio Sandoval Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2586","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2586_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2314-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Coron Elementary School in the Municipality of Coron, Province of Palawan, is changed to Claudio Sandoval Elementary School."}},{"id":"PH-H2314-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2315"] = {"id":"PH-H2315","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2587_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Lambayong, Province of Cotabato, to Sultan sa Baroñgis","orig":"An Act Changing the Name of the Municipality of Lambayong, Province of Cotabato, to Sultan sa Baroñgis"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2587","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2587_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2315-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Lambayong in the Province of Cotabato is changed to Sultan Sa Barongis."}},{"id":"PH-H2315-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2316"] = {"id":"PH-H2316","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2588_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Davao","orig":"An Act Creating Certain Barrios in the Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2588","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2588_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2316-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Digos, Province of Davao, are converted into barrios thereof, to wit:\n1. The sitios of Colorado to be known as the barrio of Colorado;\n2. The sitio of Balabag to be known as the barrio of Balabag;\n3. The sitio of San Miguel (Odaca) to be known as the barrio of San Miguel (Odaca);\n4. The sitio of Kiagot to be known as the barrio of Kiagot;\n5. The sitio of Tiguman to be known as the barrio of Tiguman;\n6. The sitio of Mahayahay to be known as the barrio of Mahayahay;\n7. The sitio of Lungag to be known as the barrio of Lungag; and\n8. The sitio of San Agustin to be known as the barrio of San Agustin."}},{"id":"PH-H2316-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Tigbawan, Lubganon and Boa in the Municipality of Caraga, same province, are converted into barrios of said municipality to be known as the barrios of Tigbawan, Lubganon and Boa, respectively."}},{"id":"PH-H2316-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2317"] = {"id":"PH-H2317","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2589_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrios in Certain Municipalities of the Province of Iloilo","orig":"An Act Creating Barrios in Certain Municipalities of the Province of Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2589","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2589_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2317-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Nueva Valencia, Province of Iloilo, are separated from their respective barrios and constituted as distinct and independent barrios of said municipality, to wit:\n1. The sitios of Napandong, Timuyon and Ilaya Catilaran in the barrio of Magamay, the sitios of Beta, Lumbiya and Catmon in the barrio of Lucmayan, the sitio of Sambulawa in the barrio of Tando and the sitio of Palanas in the barrio of Dolores to be known as the barrio of Napandong;\n2. The sitios of Harubharub, Pinamangkaw, Comian, Nabinbinan and Punta Lomboy in the barrio of Salvacion to be known as the barrio of San Roque;\n3. The sitios of Lanipe, Ubog, Desan and Tugpahan Sur in the barrio of Salvacion to be known as the barrio of Lanipe;\n4. The sitios of Taras, Butcanaway, Bungalon, Dawo, Sibunag, Budhi-an, Tamsic, Badiang, Tigbao, Guicay, Tipulo, Magobaye, Casili-an and Bangyan in the barrio of Calawa to be known as the barrio of San Antonio;\n5. The sitios of Bongga, Ilaya, Catilaran, Minuro, Limbiya, Punda, Utod, Inawa and Bunlao in the barrio of Igang to be known as the barrio of Santo Domingo; and\n6. The sitios of Canhawan Norte and Pacu Sur in the barrio of Igdarapdap, and the sitios of Canhawan Sur, Casling and Odiongan in the barrio of Cabalagnan to be known as the barrio of Canhawan."}},{"id":"PH-H2317-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The following sitios in the Municipality of Buenavista, same province, are separated from their respective barrios and constituted as distinct and independent barrios of said municipality, to wit:\n1. The sitio of Tastasan Sur in the barrio of Tastasan to be known as the barrio of San Isidro;\n2. The sitio of Agsanayan in the barrio of San Roque to be known as the barrio of Agsanayan;\n3. The sitio of Salag Diutay in the barrio of Zaldivar to be known as the barrio of Magsaysay;\n4. The sitio of Gaban in the barrio of San Enrique to be known as the barrio of Gaban;\n5. The sitio of M. Chavez in the barrio of Suclaran to be known as the barrio of M. Chavez; and\n6. The sitios of Calingao in the barrio of Salvacion to be known as the New Poblacion and designated as seat of the municipal government of Buenavista."}},{"id":"PH-H2317-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Ilong-Buquid in the Municipality of Barotac Viejo, same province, is converted into barrio of Ilong-Buquid."}},{"id":"PH-H2317-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2318"] = {"id":"PH-H2318","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2590_1959.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Batangas","orig":"An Act Creating Certain Barrios in the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2590","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2590_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2318-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Cumba in the barrio of Conde Itaas and the sitio of Maulabi in the barrio of San Miguel, both in the Municipality of Batangas, Province of Batangas, are separated from said barrios, and are constituted into a distinct and independent barrio of said municipality to be known as the barrio of Cumba."}},{"id":"PH-H2318-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Guinhawa in the barrio of Pinagbayanan, Municipality of Taysan, same province, is separated from said barrio, and constituted into a distinct and independent barrio of said municipality to be known as the barrio of Guinhawa."}},{"id":"PH-H2318-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Kaingin in the barrio of Natunuan, Municipality of Bauan, same province, is converted into a barrio of said municipality to be known as the barrio of Kaingin."}},{"id":"PH-H2318-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitio of Kalii in the Municipality of Talisay, same province, is converted into a barrio of said municipality to be known as the barrio of Asis."}},{"id":"PH-H2318-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitio of Kalii in the Municipality of Talisay, same province, is converted into a barrio of said municipality to be known as the barrio of Miranda."}},{"id":"PH-H2318-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2319"] = {"id":"PH-H2319","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2591_1959.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrios in Certain Municipalities of the Province of Samar","orig":"An Act Creating Barrios in Certain Municipalities of the Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2591","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2591_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2319-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Babanikhon and Julag in the Municipality of Llorente, Province of Samar, are converted into barrios of said municipality to be known as the barrios of Babanikon and Julag, respectively."}},{"id":"PH-H2319-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Cantenio in the Municipality of Quinapundan, same province, is converted into a barrio of said municipality to be known as the barrio of Cantenio."}},{"id":"PH-H2319-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitios of Potong, Casoroy and Bonacan in the Municipality of San Julian, same province, are converted into barrios of said municipality to be known as the barrio of Potong, Casoroy and Bonacan, respectively."}},{"id":"PH-H2319-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Garawon and San Isidro in the Municipality of Hernani, same province, are converted into barrios of said municipality to be known as the barrios of Garawon and San Isidro, respectively."}},{"id":"PH-H2319-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Bacjao, Cansomangcay, Guinmaayohan, Santa Rosa, Guinob-an and Bita-ug in the Municipality of Balangiga, same province, are converted into barrios of said municipality to be known as the barrios of Bacjao, Candomangcay, Guinma-ayohan, Santa Rosa, Guinob-an and Bita-ug, respectively."}},{"id":"PH-H2319-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of Dacul, Burak, Gayam, Mapunod, Betoc, Papuahanand Guinto-inan in the Municipality of Taft, same province, are converted into barrios of said municipality to be known as the barrios of Dacul, Burak, Gayam, Mapunod, Betoc, Papuahan and Guinto-inan, respectively."}},{"id":"PH-H2319-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitios of Son-og, Canyomanao, Tarusan, Cabagngan, Magsaysay and Pinantao in the Municipality of Laoang, same province, are converted into barrios of said municipality to be known as the barrios of Son-og, Canyomanao, Tarusan, Cabagngan, Magsaysay and Pinantao, respectively."}},{"id":"PH-H2319-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sitios of Cag-olango and Pinayagan in the Municipality of Allen, same province, are constituted into a barrio in the said municipality to be known as the barrio of San Miguel."}},{"id":"PH-H2319-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sitios of Borac and Caranas in the Municipality of Mondragon, same province, are converted into barrios of said municipality to be known as the barrios of San Antonio and San Isidro, respectively."}},{"id":"PH-H2319-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2320"] = {"id":"PH-H2320","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2592_1959.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Camarines Sur","orig":"An Act Creating Certain Barrios in the Province of Camarines Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2592","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2592_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2320-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Catanusan, Irayang Solong, Mataoroc, Manapao and Salingongon in the Municipality of Minalabac, Province of Camarines Sur, are converted into barrios of said municipality to be known as the barrios of Catanusan, Irayang Solong, Mataoroc, Manapao and Salingongon, respectively."}},{"id":"PH-H2320-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The following sitios are constituted or converted as barrios in the Municipality of Calabanga, same province, as follows:\n1. The sitios of Buri and Kaningan into a barrio to be known as the barrio of Camuning;\n2. The sitio of San Francisco into a barrio to be known as the barrio of San Francisco;\n3. The sitio of Sibao into a barrio to be known as the barrio of Sibao;\n4. The sitio of San Pablo into a barrio to be known as the barrio of San Pablo;\n5. The sitio of Sogoan into a barrio to be known as the barrio of Lugsad;\n6. The sitios of Kinali, Punicon, Sogsong and Maybayawas into a barrio to be known as the barrio of Penada;\n7. The sitios of Tawang, Inarihan, Binaliw-gote and Quinali into a barrio to be known as the barrio of Fabrica;\n8. The sitios of Malobago and Renangan into a barrio to be known as the barrio of Balombon;\n9. The sitios of Pongod, Quehadog and Baunot (Talacop) into a barrio to be known as the barrio of Sta. Rita;\n10. The sitio of Puro into a barrio to be known as the barrio of Sta. Cruz (Quipayo);\n11. The sitios of Balentong, Anahaw, Elelocdo, Que-Olleta, Que-deleon, Panatengan, Que-Paligid, Gantilo, Gotean and Tambongon into a barrio to be known as the barrio of Balatasan;\n12. The sitios of Pacoyog, Bangko and Bacong into a barrio to be known as the barrio of Deminorog;\n13. The sitios of Queriwa, Quinali, Napotol and Manoknok into a barrio to be known as the barrio of Punta-Tarawal;\n14. The sitio of Lupi-Lupi into a barrio to be known as the barrio of Sogod;\n15. The sitio of Salvacion into a barrio to be known as the barrio of Salvacion;\n16. The sitio of San Bernardino into a barrio to be known as the barrio of San Bernardino;\n17. The sitios of Bigong, Sogod Bigong and Balod into a barrio to be known as the barrio of Bigaas; and\n18. The sitio of Binaliw into a barrio to be known as the barrio of Binaliw;"}},{"id":"PH-H2320-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The following sitios are constituted or converted as barrios in the municipality of Canaman, same province, to wit:\n1. The sitio of Cogon into a barrio to be known as the barrio of Teresita;\n2. The sitio of Gotob into a barrio to be known as the barrio of San Agustin;\n3. The eastern half of the barrio of Tacolod into a barrio to be known as the barrio of San Vicente Ferrer;\n4. The eastern half of the barrio of San Jose and the sitio of Calambog into a barrio to be known as the barrio of San Jose East; and\n5. The western half of the barrio of San Jose as the Barrio sitio of Bencay into a barrio to be known as the barrio of the San Jose West."}},{"id":"PH-H2320-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Sitios of Kilantao, Calancaan, Waquit, Catalotoan and Tarobog in the Municipality of Sagnay, same province, are constituted into a barrio of said municipality to be known as the barrio of Kilantao."}},{"id":"PH-H2320-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2321"] = {"id":"PH-H2321","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2593_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Palawan","orig":"An Act Creating Certain Barrios in the Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2593","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2593_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2321-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Panitian, Odiong, Malatgao, Tagpisa, Candis and Napwaran in the Municipality of Quezon, Province of Palawan, are constituted into a distinct and independent barrio of said municipality to be known as the barrio of Panitian."}},{"id":"PH-H2321-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Calatubog in the Municipality of Puerto Princesa, same province, is converted into a barrio of said municipality to be known as the barrio of Calatubog."}},{"id":"PH-H2321-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2322"] = {"id":"PH-H2322","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2594_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of Barrios in the Municipality of Lemery, Province of Iloilo","orig":"An Act Changing the Names of Barrios in the Municipality of Lemery, Province of Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2594","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2594_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2322-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the following barrios in the Municipality of Lemery, Province of Iloilo, are changed as follows:\n1. Barrio Tuguis to Barrio Jose Almenana;\n2. Barrio Nabaloto to Barrio Pedro Velasco;\n3. Barrio Tuburan to Barrio Inocencio Sepanton;\n4. Barrio Alaguingay to Barrio Patricio Alcantara; and\n5. Barrio Bajo to Barrio San Diego."}},{"id":"PH-H2322-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2323"] = {"id":"PH-H2323","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2595_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Babatngon市","en":"An Act Creating the Barrio of Pagsulhogon in the Municipality of Babatngon, Province of Leyte","orig":"An Act Creating the Barrio of Pagsulhogon in the Municipality of Babatngon, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2595","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2595_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2323-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Pagsulhogon in the Municipality of Babatngon, Province of Leyte, is converted into a barrio of said municipality to be known as the barrio of Pagsulhogon."}},{"id":"PH-H2323-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2324"] = {"id":"PH-H2324","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2596_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Dividing the Barrio of Casibarag in the Municipality of Cabagan, Province of Isabela, into Two Barrios to be Known as Casibarag Norte and Casibarag Sur","orig":"An Act Dividing the Barrio of Casibarag in the Municipality of Cabagan, Province of Isabela, into Two Barrios to be Known as Casibarag Norte and Casibarag Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2596","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2596_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2324-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Casibarag in the Municipality of Cabagan, Province of Isabela, is hereby divided into two barrios to be known as Casibarag Norte and Casibarag Sur."}},{"id":"PH-H2324-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
  FT["PH-H2325"] = {"id":"PH-H2325","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2597_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Create Certain Barrios in the Municipality of Bolinao, Province of Pangasinan","orig":"An Act to Create Certain Barrios in the Municipality of Bolinao, Province of Pangasinan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2597","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2597_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2325-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios are constituted into distinct and separate barrios of the Municipality of Bolinao, Province of Pangasinan:\n1. The sitios of Repay Sapa, Ibabasat, Pingol and Tayao into Barrio Victory;\n2. The sitios of Matber, Tilna and Bulac-bulac into barrio Goyoden;\n3. The sitios of Dalan Bubon, Pamarbaran, Balungbong, Namlangan, Capas, Mateo and Nalsoc into Barrio Catuday;\n4. The sitios of Natulang, Nacaanoran, Macabet Norte, Poro Omic, Nasipit and Dalamas into Barrio San Roque;\n5. The sitios of Manulumanat Sur, Ca-butan, Ranom Biala, Nigagalantay, Bayoy and Sabutan into Barrio Samang;\n6. The sitios of Catubig Norte, Nanaytayan, Opay, Bongco-an, Mabalanac, Sinora, Ma-bot, Silag, Ibot, Maniorang, Talog-tog Barit, Patag Ranaw and Ilog-Balo into Barrio Tara;\n7. The sitios of Pansor, Madacay, Pandam, Lubigan, Maimpis, Pinadulang and Salumague into Barrio Cabuyao;\n8. The sitios of Banawang, Codelem, Matapopo, Cagange, Taal and Dalan Cabog into Barrio Estanza;\n9. The sitios of Paraguing, Manulumanat Norte, Sumaracasac, Tudo, Maro-mot, Nangadian Obe and Pocal-pocal into Barrio Tupa; and\n10. The sitios of Bersang, Imbo as Lomboy, Dalan Salumangue, Sapa Silag and Anonang into Barrio Liwa-liwa."}},{"id":"PH-H2325-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p32"};
